CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, full_name TEXT, organisation TEXT, role TEXT DEFAULT 'user' CHECK (role IN ('user','admin')), credits INTEGER DEFAULT 3 CHECK (credits >= 0), created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS assessments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID REFERENCES users(id) ON DELETE SET NULL, assessment_id TEXT UNIQUE NOT NULL, phase INTEGER DEFAULT 1 CHECK (phase BETWEEN 1 AND 4), contract_type TEXT, contract_category TEXT CHECK (contract_category IS NULL OR contract_category IN ('B2B','B2C')), claim_value NUMERIC CHECK (claim_value IS NULL OR claim_value >= 0), overall_verdict TEXT, probability INTEGER CHECK (probability IS NULL OR probability BETWEEN 0 AND 100), relief JSONB DEFAULT '{}'::jsonb, issues JSONB DEFAULT '[]'::jsonb, governance JSONB DEFAULT '{}'::jsonb, raw_input JSONB DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS payments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID REFERENCES users(id) ON DELETE CASCADE, package TEXT NOT NULL, amount_gbp NUMERIC NOT NULL CHECK (amount_gbp >= 0), credits_added INTEGER NOT NULL CHECK (credits_added >= 0), status TEXT DEFAULT 'pending' CHECK (status IN ('pending','completed','failed')), stripe_session_id TEXT, created_at TIMESTAMPTZ DEFAULT NOW());
ALTER TABLE users ENABLE ROW LEVEL SECURITY; ALTER TABLE assessments ENABLE ROW LEVEL SECURITY; ALTER TABLE payments ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Users can read own data" ON users; CREATE POLICY "Users can read own data" ON users FOR SELECT USING (auth.uid() = id);
DROP POLICY IF EXISTS "Users can read own assessments" ON assessments; CREATE POLICY "Users can read own assessments" ON assessments FOR SELECT USING (auth.uid() = user_id);
DROP POLICY IF EXISTS "Users can insert own assessments" ON assessments; CREATE POLICY "Users can insert own assessments" ON assessments FOR INSERT WITH CHECK (auth.uid() = user_id);
DROP POLICY IF EXISTS "Users can read own payments" ON payments; CREATE POLICY "Users can read own payments" ON payments FOR SELECT USING (auth.uid() = user_id);
CREATE INDEX IF NOT EXISTS idx_assessments_user_id ON assessments(user_id); CREATE INDEX IF NOT EXISTS idx_assessments_created_at ON assessments(created_at DESC); CREATE INDEX IF NOT EXISTS idx_payments_user_id ON payments(user_id);
